self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => c.addAll(PRECACHE)));
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('rw-shell-') && k !== SHELL) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener('message', e => { if (e.data === 'SKIP_WAITING') self.skipWaiting(); });

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;          // streams, logos, API: straight to network
  if (req.headers.has('range')) return;
  const scope = new URL(self.registration.scope);
  const path = url.pathname.slice(scope.pathname.length);

  if (req.mode === 'navigate') {                             // app shell, works offline
    e.respondWith(caches.match(new URL('index.html', scope).href, { ignoreSearch: true }).then(r => r || fetch(req)));
    return;
  }
  if (path.startsWith('data/stations/')) {                   // stale-while-revalidate snapshots
    e.respondWith(caches.open(RUNTIME).then(async c => {
      const hit = await c.match(req);
      const net = fetch(req).then(r => { if (r.ok) c.put(req, r.clone()); return r; }).catch(() => hit);
      return hit || net;
    }));
    return;
  }
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(r => {
    if (r.ok && (path.startsWith('vendor/') || path.startsWith('flags/') || path.startsWith('icons/'))) {
      const copy = r.clone(); caches.open(RUNTIME).then(c => c.put(req, copy));
    }
    return r;
  })));
});
